def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        grid[x][y] = value

    # Initialize the maximum sum for each cell
    max_sum = [[0] * N for _ in range(N)]

    # Fill the max_sum grid
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                max_sum[i][j] = grid[i][j]
            elif i == 0:
                max_sum[i][j] = max_sum[i][j-1] + grid[i][j]
            elif j == 0:
                max_sum[i][j] = max_sum[i-1][j] + grid[i][j]
            else:
                max_sum[i][j] = max(max_sum[i-1][j], max_sum[i][j-1]) + grid[i][j]

    # The maximum sum of values collected on the two paths is the maximum value in the bottom-right corner
    return max_sum[N-1][N-1]

