def generate_numbers(n, rules) -> int:
    if not rules:
        return 1  # If no rules, the number itself is considered unique

    # Convert the number to a string to easily iterate over each digit
    num_str = str(n)
    unique_numbers = set()

    # Use a queue for BFS
    queue = deque([num_str])

    while queue:
        current_num = queue.popleft()
        if current_num in unique_numbers:
            continue  # Skip duplicates

        unique_numbers.add(current_num)

        # Apply each rule to the current number
        for rule in rules:
            for i in range(len(current_num)):
                if current_num[i] == rule[0]:
                    new_num = current_num[:i] + rule[1] + current_num[i+1:]
                    queue.append(new_num)

    return len(unique_numbers)

