def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    plaintext = ""

    for i in range(len(ciphertext)):
        char = ciphertext[i]
        if char.isalpha():
            shift = ord(key[i % key_length]) - ord('A')
            if char.isupper():
                plaintext += chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
            else:
                plaintext += chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        else:
            plaintext += char

    return plaintext

def mod_inverse(a, b):
    if b == 0:
        return None  # No modular inverse exists if b is 0

    x, y, u, v = 1, 0, 0, 1
    while b != 0:
        q = a // b
        a, b = b, a % b
        x, u = u, x - q * u
        y, v = v, y - q * v

    if x < 0:
        x += b

    return x

